def run_lru_ops(capacity, ops, args):
    cache = LRUCache(capacity)
    results = []
    for op, a in zip(ops, args):
        if op == "put":
            cache.put(a[0], a[1])
        elif op == "get":
            results.append(cache.get(a[0]))
    return results

