public static class LruHarness
{
    public static List<int> Run(int capacity, string[] ops, int[][] args)
    {
        var cache = new LRUCache(capacity);
        var results = new List<int>();
        for (var i = 0; i < ops.Length; i++)
        {
            if (ops[i] == "put") cache.Put(args[i][0], args[i][1]);
            else if (ops[i] == "get") results.Add(cache.Get(args[i][0]));
        }
        return results;
    }
}

